"""Record inspected source passages and a proposed reported-basis OCF map once."""
import hashlib,json,os
from pathlib import Path

U=Path(__file__).resolve().parent; R=U.parents[2]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
bind=lambda p:{'path':str(p.relative_to(R)),'sha256':sha(p)}
load=lambda p:json.loads(p.read_text())

# LF-line ranges actually inspected in this unit. Labels/amounts are transcriptions,
# not automatic semantic or original-release admissions.
SPECS={
 'apple': {'ranges':[(1352,1361),(1408,1416),(2832,2833)], 'label':'Cash generated by operating activities',
           'amount':'111482','currency_display':'$','currency_proposal':'USD','multiplier':1000000,
           'basis':'US GAAP','column':'2025, first amount','risk':'not the change in cash or net income'},
 'caterpillar': {'ranges':[(3356,3361),(3374,3378),(3028,3030),(2173,2173),(3512,3515)],
           'label':'Net cash provided by (used for) operating activities','amount':'11739',
           'currency_display':'dollars','currency_proposal':'USD','multiplier':1000000,
           'basis':'US GAAP','column':'2025, first amount','risk':'MP&E operating cash 12278 is a narrower scope'},
 'jpmorgan': {'ranges':[(12381,12385),(12394,12404),(12459,12472)],
           'label':'Net cash (used in)/provided by operating activities','amount':'-147782',
           'currency_display':'$','currency_proposal':'USD','multiplier':1000000,
           'basis':'US GAAP plus applicable regulatory guidelines','column':'2025, first amount',
           'risk':'parentheses are a negative cash flow, not missing data'},
 'henkel': {'ranges':[(19896,19924),(20171,20184),(20774,20779),(20836,20844)],
           'label':'Cash flow from operating activities','amount':'2535',
           'currency_display':'million euros','currency_proposal':'EUR','multiplier':1000000,
           'basis':'IFRS as adopted under EU Regulation 1606/2002 plus HGB 315e',
           'column':'2025, second amount after 2024','risk':'first numeric column is 2024; interest received/paid appear in other cash-flow sections'},
 'hsbc': {'ranges':[(21850,21854),(21866,21882),(22157,22161),(22174,22177),(22248,22254),(22281,22286),(22297,22303)],
           'label':'Net cash from operating activities','amount':'29766',
           'currency_display':'$m; reporting currency US dollars','currency_proposal':'USD','multiplier':1000000,
           'basis':'UK-adopted international standards, EU-adopted IFRS, and IASB IFRS as attributed in note 1.1',
           'column':'2025, first amount','risk':'HSBC Holdings separate-company amount 16723 is a different perimeter'},
 'munich_re': {'ranges':[(14363,14388),(14436,14448),(15929,15944)],
           'label':'I. Cash flows from operating activities','amount':'4906',
           'currency_display':'€m','currency_proposal':'EUR','multiplier':1000000,
           'basis':'IFRS as adopted by EU plus HGB 315e(1)','column':'2025, first amount',
           'risk':'retained text has damaged thousands separators; amount visually read on physical page 232, printed 230; prior-year figures adjusted under IAS 8'},
 'saic_motor': {'ranges':[(3708,3718),(3743,3750),(3798,3801),(3810,3813),(4183,4189)],
           'label':'经营活动产生的现金流量净额','amount':'34306601905.98',
           'currency_display':'单位：元 币种：人民币','currency_proposal':'CNY','multiplier':1,
           'basis':'PRC enterprise accounting standards and CSRC report disclosures',
           'column':'2025年度, first amount','risk':'mother-company OCF -1927967480.42 differs; finance-subsidiary flows included'},
 'ping_an': {'ranges':[(8929,8939),(8965,8971),(9317,9321),(9352,9355),(9973,9978)],
           'label':'经营活动产生的现金流量净额','amount':'658632',
           'currency_display':'人民币百万元','currency_proposal':'CNY','multiplier':1000000,
           'basis':'PRC enterprise accounting standards and CSRC report disclosures',
           'column':'2025年度, first amount','risk':'repo/reverse-repo cash flows classified differently for bank/securities and insurance businesses'},
 'midea': {'ranges':[(8265,8273),(8280,8295),(8535,8541),(8555,8559)],
           'label':'经营活动产生/(使用)的现金流量净额','amount':'53345930',
           'currency_display':'人民币千元','currency_proposal':'CNY','multiplier':1000,
           'basis':'PRC enterprise accounting standards and CSRC report disclosures',
           'column':'2025年度 合并, first of four amounts','risk':'2025 parent column is -11628058; thousand-unit scale differs from million-unit reports'}
}


def main():
    assert os.environ.get('CUDA_VISIBLE_DEVICES')=='-1'
    assert not (U/'measurement-map.json').exists()
    covpath=R/'data/financial-report-benchmark/coverage.json'; cov=load(covpath)
    rows=[]
    for n,r in enumerate(cov['rows']):
        if r['period_year']!=2025 or r['report_class']!='annual':continue
        spec=dict(SPECS[r['issuer_id']]);ranges=spec.pop('ranges')
        txt,original=R/r['extracted_text_path'],R/r['local_path']
        assert sha(original)==r['sha256']
        lines=txt.read_text().split('\n')
        anchors=[{'start_line':a,'end_line':b,'quote':'\n'.join(lines[a-1:b])} for a,b in ranges]
        rows.append({'issuer_id':r['issuer_id'],'document_id':r['document_id'],
                     'source_url':r['source_url'],'coverage_pointer':f'/rows/{n}',
                     'original':bind(original),'text':bind(txt),'anchors':anchors,
                     'financial_scope_proposal':'consolidated group as reported, not constant composition',
                     'calendar_record':'data/accounting-master/r05-fiscal-year-protocol-20261023/calendar-sources.json',
                     'reported_value':spec,'measurement_status':'author_checked_candidate_mapping',
                     'first_release_admitted':False,'historical_vintage_admitted':False,
                     'accounting_harmonization_admitted':False,'independent_gold':False})
    assert len(rows)==9
    record={'scope':'reported consolidated net operating-cash-flow mapping candidates, FY2025 annual reports',
            'coverage':bind(covpath),'line_convention':'one-based LF lines, form feeds retained',
            'rows':rows,'rendered_source_review':{
                'path':str((U/'munich-cash-flow-page232.png').relative_to(R)),
                'sha256':sha(U/'munich-cash-flow-page232.png'),'physical_page':232,'printed_page':230,
                'actually_viewed':True,'observed_2025_ocf_eur_million':'4906',
                'footnote':'Previous year figures adjusted pursuant to IAS 8',
                'render_command':'pdftoppm -f 232 -l 232 -r 110 -singlefile -png data/financial-report-benchmark/documents/munich_re/munich_re-2025-annual/original.pdf data/accounting-master/r05-ocf-measurement-20261023/munich-cash-flow-page232'},
            'source_claims_only':'Accounting basis and future-standard effects are issuer assertions, not independently adjudicated compliance or standard interpretation',
            'future_reporting_transition':'Henkel, HSBC and Munich Re disclose IFRS18/IAS7 presentation implications from 2027; quantification/authority not established here'}
    with (U/'measurement-map.json').open('x') as f:
        json.dump(record,f,ensure_ascii=False,indent=2);f.write('\n')
    print(json.dumps({'issuer_mapping_candidates':9,'text_anchors':sum(len(r['anchors']) for r in rows),
                      'source_pages_actually_viewed':1,'first_release_admissions':0}))


if __name__=='__main__':main()
